from pybricks.hubs import PrimeHub
from pybricks.iodevices import XboxController
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
leftMotor = Motor(Port.A, Direction.COUNTERCLOCKWISE)
rightMotor = Motor(Port.E, Direction.CLOCKWISE)
DriveBase1 = DriveBase(leftMotor, rightMotor, 68.8, 6 * 25.4)
TopAttach = Motor(Port.B, Direction.CLOCKWISE)
SideAttach = Motor(Port.F, Direction.CLOCKWISE)
colorSensor = ColorSensor(Port.C)
controller = XboxController()
speed = 1


# The main program starts here.
print('Hello, Pybricks!')
SideAttach.control.limits(acceleration=2000)
SideAttach.run_angle(10000, 360)
